n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 12px;\n}\n\n.item-card {\n  background: #fcf8f0;\n  border: 2px solid #e4d4ba;\n  border-radius: 12px;\n  padding: 16px;\n  text-align: center;\n  transition: all 0.2s;\n\n  &:hover {\n    border-color: #c8955c;\n    transform: scale(1.03);\n  }\n}\n\n.item-icon {\n  font-size: 2.2rem;\n  display: block;\n  margin-bottom: 8px;\n}\n\n.item-name {\n  font-weight: 900;\n  font-size: 0.82rem;\n  color: #5c4738;\n  display: block;\n}\n\n.item-qty {\n  font-size: 0.7rem;\n  font-weight: 900;\n  color: #a88a6d;\n  background: #f4ecdb;\n  padding: 2px 6px;\n  border-radius: 4px;\n  margin-top: 6px;\n  display: inline-block;\n}\n\n.w-full {\n  width: 100%;\n  padding: 14px;\n}\n\n.plan-modal {\n  max-width: 560px;\n  width: min(96vw, 560px);\n}\n\n.plan-tabs {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 10px;\n  margin-bottom: 12px;\n}\n\n.plan-tab {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 6px;\n  padding: 12px;\n  border: 2px solid #8c7462;\n  border-radius: 12px;\n  background: #fcf8f0;\n  font-weight: 900;\n  font-size: 0.85rem;\n  color: #6b4c3a;\n  cursor: pointer;\n  font-family: inherit;\n\n  &.active {\n    border-color: #4a7c59;\n    background: #e8f3eb;\n    color: #3d5c45;\n  }\n}\n\n.plan-detail {\n  min-height: 240px;\n  max-height: 420px;\n  border: 2px dashed #e4d4ba;\n  border-radius: 14px;\n  background: #fcf8f0;\n  padding: 14px;\n  margin-bottom: 14px;\n}\n\n.catalog-grid {\n  display: grid;\n  grid-template-columns: repeat(2, 1fr);\n  gap: 10px;\n  margin-top: 10px;\n}\n\n@media (max-width: 520px) {\n  .catalog-grid {\n    grid-template-columns: 1fr;\n  }\n}\n\n.plan-info {\n  h4 {\n    margin: 0 0 10px;\n    font-size: 0.95rem;\n    font-weight: 900;\n    color: #3d5c45;\n  }\n}\n\n.info-row {\n  margin: 6px 0;\n  font-size: 0.78rem;\n  font-weight: 700;\n  color: #5c4738;\n  line-height: 1.45;\n\n  span {\n    font-weight: 900;\n    color: #4a7c59;\n    margin-right: 6px;\n  }\n}\n\n.form-field.compact {\n  margin-bottom: 10px;\n}\n\n.plan-confirm {\n  margin-top: 0;\n\n  &:disabled {\n    opacity: 0.45;\n    cursor: not-allowed;\n  }\n}\n\n.plan-preview {\n  background: #f4ecdb;\n  border: 2px dashed #c8955c;\n  border-radius: 12px;\n  padding: 14px;\n  margin-bottom: 16px;\n}\n\n.plan-preview-title {\n  margin: 0 0 10px;\n  font-size: 0.82rem;\n  font-weight: 900;\n  color: #5c4738;\n}\n\n.plan-preview-row {\n  display: flex;\n  gap: 10px;\n  margin: 6px 0;\n  font-size: 0.85rem;\n  font-weight: 700;\n  color: #6b4c3a;\n}\n\n.plan-preview-label {\n  flex-shrink: 0;\n  font-weight: 900;\n  color: #8c7462;\n  min-width: 2.5em;\n}\n\n.plan-preview-hint {\n  margin: 10px 0 0;\n  font-size: 0.72rem;\n  font-weight: 800;\n  color: #4a7c59;\n\n  &.shortage {\n    color: #d9776c;\n  }\n}\n\n.materials-box {\n  background: #fdf6e8;\n  border-color: #c8955c;\n}\n\n.hours-box {\n  background: #eef0f5;\n  border-color: #8c7462;\n}\n\n.facility-modal {\n  max-width: 720px;\n  position: relative;\n  overflow: hidden;\n  padding-top: 18px;\n  padding-bottom: 18px;\n}\n\n.facility-layout {\n  display: flex;\n  align-items: stretch;\n  max-height: 68vh;\n  min-height: 260px;\n  overflow: hidden;\n}\n\n.facility-list {\n  width: 50%;\n  padding-right: 14px;\n  border-right: 2px dashed #e4d4ba;\n  overflow-y: auto;\n\n  h3 {\n    font-size: 1.2rem;\n    font-weight: 900;\n    margin: 0 0 14px;\n    color: #5c4738;\n    display: flex;\n    align-items: center;\n    gap: 8px;\n  }\n}\n\n.facility-item {\n  display: block;\n  width: 100%;\n  text-align: left;\n  padding: 14px;\n  margin-bottom: 8px;\n  border: 2px solid #d4c2a4;\n  border-radius: 12px;\n  background: #fcf8f0;\n  font-family: inherit;\n  font-weight: 900;\n  color: #4a3b32;\n  cursor: pointer;\n  transition: background 0.15s;\n\n  &:hover {\n    background: #fffdf8;\n  }\n\n  &.active {\n    background: #f4ecdb;\n    border-color: #c8955c;\n  }\n}\n\n.facility-detail {\n  width: 50%;\n  padding-left: 20px;\n  overflow: hidden;\n\n  h4 {\n    font-size: 1.3rem;\n    font-weight: 900;\n    color: #4a3b32;\n    margin: 0 0 10px;\n    padding-top: 0;\n  }\n}\n\n.detail-box {\n  background: #fcf8f0;\n  border: 2px solid #e4d4ba;\n  border-radius: 12px;\n  padding: 12px;\n  margin-bottom: 12px;\n\n  p {\n    margin: 0;\n    font-weight: 700;\n    color: #8c7462;\n    font-size: 0.88rem;\n    line-height: 1.5;\n  }\n}\n\n.effect-box {\n  margin-top: 12px;\n  background: #eef5ef;\n  border: 1px solid #7ca982;\n  border-radius: 8px;\n  padding: 10px;\n  font-weight: 700;\n  font-size: 0.85rem;\n  color: #5c4738;\n\n  .effect-label {\n    display: block;\n    font-size: 0.68rem;\n    font-weight: 900;\n    color: #4a7c59;\n    margin-bottom: 4px;\n  }\n}\n\n.facility-actions {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  padding-top: 10px;\n  border-top: 2px dashed #e4d4ba;\n\n  .actions-label {\n    font-size: 0.82rem;\n    font-weight: 900;\n    color: #8c7462;\n  }\n\n  button {\n    padding: 10px;\n    font-size: 0.88rem;\n  }\n}\n\n.facility-empty {\n  width: 50%;\n  padding-left: 24px;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  text-align: center;\n  color: #a88a6d;\n  font-weight: 700;\n\n  .empty-icon {\n    opacity: 0.2;\n    margin-bottom: 16px;\n  }\n}\n\n.empty-hint {\n  text-align: center;\n  color: #8c7462;\n  font-weight: 700;\n  padding: 20px;\n}\n\n@media (max-width: 640px) {\n  .camp-layout {\n    grid-template-columns: 1fr;\n  }\n\n  .facility-layout {\n    flex-direction: column;\n  }\n\n  .facility-list,\n  .facility-detail,\n  .facility-empty {\n    width: 100%;\n    border-right: none;\n    padding: 0;\n  }\n\n  .facility-list {\n    border-bottom: 2px dashed #e4d4ba;\n    padding-bottom: 16px;\n    margin-bottom: 16px;\n  }\n}\n"],"sourceRoot":""}]);
