 align-items: center;\n  gap: 5px;\n  color: #e8789a;\n}\n\n.cub-avatar-placeholder {\n  width: 88px;\n  height: 88px;\n  border-radius: 50%;\n  border: 4px solid #e8789a;\n  background: #fce8ef;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  position: relative;\n  flex-shrink: 0;\n\n  .cub-avatar-icon {\n    position: absolute;\n    color: #f0b8c8;\n    opacity: 0.55;\n  }\n\n  .avatar-letter {\n    z-index: 1;\n    color: #c94d73;\n  }\n}\n\n.cubs-icon {\n  color: #e8789a;\n}\n\n.cub-rule-banner {\n  margin: -8px 0 4px;\n  padding: 12px 14px;\n  border: 2px dashed #e8a0b8;\n  border-radius: 14px;\n  background: #fff8fa;\n}\n\n.cub-rule-label {\n  margin: 0 0 6px;\n  font-size: 0.72rem;\n  font-weight: 900;\n  color: #e8789a;\n  letter-spacing: 0.06em;\n}\n\n.cub-rule-text {\n  margin: 0;\n  font-size: 0.8rem;\n  font-weight: 700;\n  color: #8c5a6a;\n  line-height: 1.55;\n}\n\n.cub-growth-box {\n  margin-top: 16px;\n  padding: 14px 16px;\n  border: 2px dashed #e8a0b8;\n  border-radius: 14px;\n  background: #fff8fa;\n}\n\n.cub-growth-label {\n  margin: 0 0 8px;\n  font-size: 0.72rem;\n  font-weight: 900;\n  color: #e8789a;\n  letter-spacing: 0.06em;\n}\n\n.cub-growth-text {\n  margin: 0;\n  font-size: 0.82rem;\n  font-weight: 700;\n  color: #8c5a6a;\n  line-height: 1.55;\n}\n\n.readonly-avatar {\n  cursor: default;\n}\n\n.npc-role.muted {\n  color: #9a8b72;\n  font-style: italic;\n}\n\n.skill-section {\n  margin-top: 4px;\n  padding: 12px;\n  border: 2px dashed #e4d4ba;\n  border-radius: 12px;\n  background: #faf6ee;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.skill-section-title {\n  margin: 0;\n  font-size: 13px;\n  font-weight: 700;\n  color: #6b5a42;\n}\n\n.skill-row {\n  display: grid;\n  grid-template-columns: 18px 36px 1fr 32px;\n  align-items: center;\n  gap: 6px;\n}\n\n.skill-icon {\n  color: #8a7a62;\n}\n\n.skill-label {\n  font-size: 13px;\n  color: #5c4f3a;\n  font-weight: 600;\n}\n\n.skill-bar-track {\n  flex: 1;\n  height: 12px;\n  border-radius: 999px;\n  background: #ebe2d0;\n  overflow: visible;\n  position: relative;\n  border: 1px solid rgba(180, 140, 90, 0.35);\n  box-shadow: inset 0 1px 3px rgba(92, 71, 56, 0.08);\n}\n\n.skill-bar-fill {\n  height: 100%;\n  border-radius: 999px;\n  position: relative;\n  transition: width 0.2s;\n\n  &::after {\n    content: '';\n    position: absolute;\n    right: -2px;\n    top: 50%;\n    width: 14px;\n    height: 14px;\n    transform: translateY(-50%);\n    border-radius: 50%;\n    background: radial-gradient(circle at 35% 30%, #f5efe3 0%, #c9a574 55%, #967048 100%);\n    border: 1.5px solid #a88452;\n    box-shadow: 0 1px 3px rgba(92, 71, 56, 0.2);\n  }\n\n  &.skill-狩猎 {\n    background: linear-gradient(90deg, #c47a4a, #e8a06a);\n  }\n\n  &.skill-战斗 {\n    background: linear-gradient(90deg, #b54a4a, #e07070);\n  }\n\n  &.skill-采集 {\n    background: linear-gradient(90deg, #5a9a5a, #7cb87c);\n  }\n\n  &.skill-后勤 {\n    background: linear-gradient(90deg, #6a8ab5, #8aaed8);\n  }\n}\n\n.skill-value {\n  font-size: 12px;\n  font-weight: 700;\n  color: #5c4f3a;\n  text-align: right;\n  cursor: help;\n}\n\n.members-layout {\n  display: flex;\n  min-width: 0;\n  width: 100%;\n  min-height: 320px;\n  overflow: hidden;\n  background: rgba(253, 251, 245, 0.92);\n  border-color: #d4c4a8;\n}\n\n.member-sidebar {\n  flex: 0 0 38%;\n  max-width: 220px;\n  min-width: 0;\n  border-right: 2px dashed #e4d4ba;\n  padding: 12px;\n  overflow-y: auto;\n  overflow-x: hidden;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.sidebar-item {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  width: 100%;\n  padding: 10px;\n  border: 2px solid #e4d4ba;\n  border-radius: 14px;\n  background: #fcf8f0;\n  cursor: pointer;\n  text-align: left;\n  font-family: inherit;\n  transition: border-color 0.15s, background 0.15s;\n\n  &:hover {\n    background: #fffdf8;\n    border-color: #d4c2a4;\n  }\n\n  &.active {\n    background: #f4ecdb;\n    border-color: #c8955c;\n    box-shadow: 0 2px 6px rgba(200, 149, 92, 0.2);\n  }\n}\n\n.sidebar-avatar {\n  width: 44px;\n  height: 44px;\n  border-radius: 12px;\n  background: #dcd1be;\n  border: 2px solid #c8955c;\n  flex-shrink: 0;\n  overflow: hidden;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  position: relative;\n}\n\n.sidebar-meta {\n  min-width: 0;\n  flex: 1;\n}\n\n.sidebar-name {\n  display: block;\n  font-weight: 900;\n  color: #4a3b32;\n  font-size: 0.95rem;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.sidebar-race {\n  display: inline-block;\n  margin-top: 2px;\n  font-size: 0.62rem;\n  background: #e4d4ba;\n  color: #6b4c3a;\n  padding: 1px 6px;\n  border-radius: 999px;\n  font-weight: 800;\n}\n\n.sidebar-stats {\n  display: flex;\n  gap: 10px;\n  margin-top: 4px;\n  font-size: 0.68rem;\n  font-weight: 900;\n}\n\n.member-detail {\n  flex: 1 1 auto;\n  min-width: 0;\n  padding: 20px;\n  position: relative;\n  overflow-y: auto;\n}\n\n.expel-btn {\n  position: absolute;\n  top: 16px;\n  right: 16px;\n  color: #d9776c;\n  background: transparent;\n  border: none;\n  padding: 8px;\n  border-radius: 12px;\n  cursor: pointer;\n  z-index: 2;\n\n  &:hover {\n    color: #a8543f;\n    background: #f4d8d3;\n  }\n}\n\n.detail-head {\n  display: flex;\n  gap: 16px;\n  margin-bottom: 16px;\n  padding-right: 40px;\n}\n\n.avatar-label {\n  width: 80px;\n  height: 80px;\n  border-radius: 16px;\n  background: #dcd1be;\n  border: 3px solid #c8955c;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  flex-shrink: 0;\n  cursor: pointer;\n  overflow: hidden;\n  position: relative;\n  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.08);\n}\n\n.avatar-img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n}\n\n.avatar-bg-icon {\n  position: absolute;\n  color: #a88a6d;\n  opacity: 0.3;\n}\n\n.avatar-letter {\n  font-size: 1.4rem;\n  font-weight: 900;\n  color: #5c4738;\n  z-index: 1;\n\n  &.lg {\n    font-size: 2rem;\n  }\n}\n\n.avatar-hover {\n  position: absolute;\n  inset: 0;\n  background: rgba(0, 0, 0, 0.4);\n  color: #fff;\n  font-size: 0.7rem;\n  font-weight: 800;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  opacity: 0;\n  transition: opacity 0.2s;\n  z-index: 2;\n}\n\n.group-avatar:hover .avatar-hover {\n  opacity: 1;\n}\n\n.hidden-input {\n  display: none;\n}\n\n.npc-name {\n  margin: 0;\n  font-size: 1.35rem;\n  font-weight: 900;\n  color: #4a3b32;\n  display: flex;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 8px;\n}\n\n.npc-race {\n  font-size: 0.68rem;\n  background: #e4d4ba;\n  color: #6b4c3a;\n  padding: 2px 8px;\n  border-radius: 999px;\n  font-weight: 800;\n  border: 1px solid #d4c2a4;\n}\n\n.npc-role-row {\n  display: flex;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 10px;\n  margin-top: 4px;\n}\n\n.npc-role {\n  margin: 0;\n  font-size: 0.82rem;\n  font-weight: 700;\n  color: #8c7462;\n}\n\n.npc-grade {\n  display: inline-flex;\n  align-items: center;\n  padding: 2px 10px;\n  border-radius: 999px;\n  font-size: 0.75rem;\n  font-weight: 900;\n  letter-spacing: 0.04em;\n  border: 1.5px solid currentColor;\n}\n\n.npc-grade.grade-beginner {\n  color: #2e7d32;\n  background: rgba(76, 175, 80, 0.12);\n}\n\n.npc-grade.grade-entry {\n  color: #1565c0;\n  background: rgba(33, 150, 243, 0.12);\n}\n\n.npc-grade.grade-skilled {\n  color: #c62828;\n  background: rgba(229, 57, 53, 0.12);\n}\n\n.npc-grade.grade-master {\n  color: #f57f17;\n  background: rgba(249, 168, 37, 0.16);\n}\n\n.npc-pregnancy {\n  margin: 0;\n  font-size: 0.82rem;\n  font-weight: 800;\n  color: #e8789a;\n  letter-spacing: 0.04em;\n}\n\n.npc-stats {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 14px;\n  margin-top: 10px;\n}\n\n.macaron-stats {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 10px;\n  width: 100%;\n  max-width: 360px;\n}\n\n.macaron-stats-single {\n  grid-template-columns: minmax(0, 1fr);